fn frame(t: i32) {
    let w: i32 = host::display::width();
    let h: i32 = host::display::height();
    let down: i32 = host::display::pointer_down();
    let prev: i32 = host::display::state_get(0);
    if down == 1 && prev == 0 {
        let row: i32 = host::display::pointer_y() * 3 / h;
        if row == 0 {
            let mut i: i32 = 0;
            while i < 6 {
                host::audio::tone_at(1200 - i * 150, 60, 2, i * 40);
                i = i + 1;
            }
        }
        if row == 1 {
            host::audio::noise(400);
        }
        if row >= 2 {
            let mut j: i32 = 0;
            while j < 5 {
                host::audio::tone_at(300 + j * 120, 70, 1, j * 60);
                j = j + 1;
            }
        }
    }
    host::display::state_set(0, down);
    host::display::clear(0x000000);
    host::display::fill_rect(6, 6, w - 12, h / 3 - 12, 0x201038);
    host::display::fill_rect(6, h / 3 + 6, w - 12, h / 3 - 12, 0x381010);
    host::display::fill_rect(6, h * 2 / 3 + 6, w - 12, h / 3 - 12, 0x103818);
    host::display::draw_string(24, h / 6, "LASER", 0xffffff, 3);
    host::display::draw_string(24, h / 2, "BOOM", 0xffffff, 3);
    host::display::draw_string(24, h * 5 / 6, "POWERUP", 0xffffff, 3);
    host::display::present();
}
